// index.js
import './style.css';
import { TodoApp, createTodo } from './components/todo-app.js';

const app = new TodoApp();

const projectListEl = document.getElementById('project-list');
const todoListEl = document.getElementById('todo-list');
const newProjectInput = document.getElementById('new-project-name');
const addProjectBtn = document.getElementById('add-project-btn');

const todoTitleInput = document.getElementById('todo-title');
const todoDescInput = document.getElementById('todo-desc');
const todoDueDateInput = document.getElementById('todo-due-date');
const todoPrioritySelect = document.getElementById('todo-priority');
const addTodoBtn = document.getElementById('add-todo-btn');

function priorityClass(priority) {
  switch (priority) {
    case 'high': return 'high-priority';
    case 'medium': return 'medium-priority';
    case 'low': return 'low-priority';
    default: return '';
  }
}

function renderProjects() {
  projectListEl.innerHTML = '';
  app.getProjects().forEach(projName => {
    const div = document.createElement('div');
    div.className = 'project-item';
    if (projName === app.currentProjectId) div.classList.add('active');
    div.textContent = projName;

    div.addEventListener('click', () => {
      app.setCurrentProject(projName);
      renderAll();
    });

    if (projName !== 'default') {
      const delBtn = document.createElement('button');
      delBtn.textContent = '删除';
      delBtn.style.marginLeft = '10px';
      delBtn.addEventListener('click', e => {
        e.stopPropagation();
        if (confirm(`确定删除项目 "${projName}" 及其所有待办事项？`)) {
          try {
            app.deleteProject(projName);
            renderAll();
          } catch (err) {
            alert(err.message);
          }
        }
      });
      div.appendChild(delBtn);
    }

    projectListEl.appendChild(div);
  });
}

function renderTodos() {
  todoListEl.innerHTML = '';
  const todos = app.getTodos();

  if (todos.length === 0) {
    todoListEl.textContent = '当前项目暂无待办事项';
    return;
  }

  todos.forEach(todo => {
    const div = document.createElement('div');
    div.className = 'todo-item';

    const prioritySpan = document.createElement('span');
    prioritySpan.textContent = `[${todo.priority}] `;
    prioritySpan.className = priorityClass(todo.priority);

    const titleSpan = document.createElement('span');
    titleSpan.textContent = todo.title;
    if (todo.completed) titleSpan.style.textDecoration = 'line-through';

    const descSpan = document.createElement('div');
    descSpan.textContent = todo.description ? `描述: ${todo.description}` : '';
    const dueSpan = document.createElement('div');
    dueSpan.textContent = todo.dueDate ? `截止日期: ${todo.dueDate}` : '';

    const completeBtn = document.createElement('button');
    completeBtn.textContent = todo.completed ? '未完成' : '完成';
    completeBtn.addEventListener('click', () => {
      app.toggleComplete(todo.id);
      app.saveData();
      renderTodos();
    });

    const delBtn = document.createElement('button');
    delBtn.textContent = '删除';
    delBtn.addEventListener('click', () => {
      if (confirm('确认删除该待办事项？')) {
        app.deleteTodo(todo.id);
        app.saveData();
        renderTodos();
      }
    });

    div.appendChild(prioritySpan);
    div.appendChild(titleSpan);
    div.appendChild(completeBtn);
    div.appendChild(delBtn);
    div.appendChild(descSpan);
    div.appendChild(dueSpan);

    todoListEl.appendChild(div);
  });
}

function renderAll() {
  renderProjects();
  renderTodos();
}

function init() {
  app.loadData();
  app.setCurrentProject('default');
  renderAll();

  addProjectBtn.addEventListener('click', () => {
    try {
      app.addProject(newProjectInput.value);
      app.saveData();
      app.setCurrentProject(newProjectInput.value);
      newProjectInput.value = '';
      renderAll();
    } catch (err) {
      alert(err.message);
    }
  });

  addTodoBtn.addEventListener('click', () => {
    try {
      app.addTodo(
        todoTitleInput.value,
        todoDescInput.value,
        todoDueDateInput.value,
        todoPrioritySelect.value
      );
      app.saveData();
      todoTitleInput.value = '';
      todoDescInput.value = '';
      todoDueDateInput.value = '';
      todoPrioritySelect.value = 'medium';
      renderTodos();
    } catch (err) {
      alert(err.message);
    }
  });
}

init();