// todo-app.js
export function createTodo(id, title, description, dueDate, priority) {
  return {
    id,
    title,
    description,
    dueDate,
    priority,
    completed: false,
  };
}

function generateId() {
  return '_' + Math.random().toString(36).substr(2, 9);
}

function priorityClass(priority) {
  switch (priority) {
    case 'high': return 'high-priority';
    case 'medium': return 'medium-priority';
    case 'low': return 'low-priority';
    default: return '';
  }
}

export class TodoApp {
  constructor() {
    this.projects = {};
    this.currentProjectId = 'default';
  }

  loadData() {
    const savedData = localStorage.getItem('todoData');
    if (savedData) {
      this.projects = JSON.parse(savedData);
      if (!this.projects['default']) this.projects['default'] = [];
    } else {
      this.projects = { 'default': [] };
    }
  }

  saveData() {
    localStorage.setItem('todoData', JSON.stringify(this.projects));
  }

  setCurrentProject(id) {
    this.currentProjectId = id;
  }

  addProject(name) {
    if (!name.trim()) throw new Error('项目名称不能为空');
    if (this.projects[name]) throw new Error('项目已存在');
    this.projects[name] = [];
  }

  deleteProject(name) {
    if (name === 'default') throw new Error('默认项目无法删除');
    delete this.projects[name];
    this.currentProjectId = 'default';
  }

  addTodo(title, description, dueDate, priority) {
    if (!title.trim()) throw new Error('标题不能为空');
    const todo = createTodo(generateId(), title, description, dueDate, priority);
    this.projects[this.currentProjectId].push(todo);
  }

  deleteTodo(id) {
    this.projects[this.currentProjectId] = this.projects[this.currentProjectId].filter(todo => todo.id !== id);
  }

  toggleComplete(id) {
    const todo = this.projects[this.currentProjectId].find(t => t.id === id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  }

  getProjects() {
     return Object.keys(this.projects).filter(id => id !== 'default');
  }

  getTodos() {
    return this.projects[this.currentProjectId] || [];
  }
}